ControlPropertyState.AutoRuleBindingString:
If(
    drp_TipoEnvio_LO_1.Selected.Value = "Via Miami",
    If(
        IsBlank(dt_FechaMiami_LO_1.SelectedDate) || IsBlank(txt_refMiamo_LO_1.Text) || IsBlank(drp_MetodoTransporte_LO_1.SelectedText.Value) || IsBlank(drp_TipoEnvio_LO_1.SelectedText.Value),
        UpdateContext(
            {
                MostrarAviso: true,
                mensajeNotificacion: "Por favor asegurese de completar todos los campos de informacion requerido."
            }
        ),
        If(
            dt_FechaTech_LO_1.SelectedDate <= dt_FechaMiami_LO_1.SelectedDate,
            UpdateContext(
                {
                    MostrarAviso: true,
                    mensajeNotificacion: "La fecha TechShop debe ser mayor a la fecha de Miami."
                }
            ),
            With(
                {
                    resultado: Patch(
                        Compras_Pots,
                        LookUp(
                            Compras_Pots,
                            POT = gl_PuestoCompras_LO_1.Selected.POT
                        ),
                        {
                            Tipo_Envio: drp_TipoEnvio_LO_1.Selected.Value,
                            Transporte: drp_MetodoTransporte_LO_1.SelectedText.Value,
                            Fecha_Miami: dt_FechaMiami_LO_1.SelectedDate,
                            Fecha_Tech: dt_FechaTech_LO_1.SelectedDate,
                            Ref_Miami: txt_refMiamo_LO_1.Text,
                            Ref_Tech: txt_refTech_LO_1.Text,
                            'Estado (crfb9_estado)': "Tramitado"
                        }
                    )
                },
                UpdateContext(
                    {
                        AbrirCompletar: false,
                        seleccion: false
                    }
                );
                Refresh(Compras_Pots);
                Reset(dt_FechaMiami_LO_1);
                Reset(txt_refMiamo_LO_1);
                Reset(dt_FechaTech_LO_1);
                Reset(txt_refTech_LO_1);
                Reset(drp_MetodoTransporte_LO_1);
                Reset(drp_TipoEnvio_LO_1)
            )
        )
    ),
    If(
        IsBlank(dt_FechaTech_LO_1.SelectedDate) || IsBlank(txt_refTech_LO_1.Text) || IsBlank(drp_MetodoTransporte_LO_1.SelectedText.Value) || IsBlank(drp_TipoEnvio_LO_1.SelectedText.Value),
        UpdateContext(
            {
                MostrarAviso: true,
                mensajeNotificacion: "Por favor asegurese de completar todos los campos de informacion requerido."
            }
        ),
        With(
            {
                resultado: Patch(
                    Compras_Pots,
                    LookUp(
                        Compras_Pots,
                        POT = gl_PuestoCompras_LO_1.Selected.POT
                    ),
                    {
                        Tipo_Envio: drp_TipoEnvio_LO_1.Selected.Value,
                        Transporte: drp_MetodoTransporte_LO_1.SelectedText.Value,
                        Fecha_Miami: dt_FechaMiami_LO_1.SelectedDate,
                        Fecha_Tech: dt_FechaTech_LO_1.SelectedDate,
                        Ref_Miami: txt_refMiamo_LO_1.Text,
                        Ref_Tech: txt_refTech_LO_1.Text,
                        'Estado (crfb9_estado)': "Tramitado"
                    }
                )
            },
            UpdateContext(
                {
                    AbrirCompletar: false,
                    seleccion: false
                }
            );
            Refresh(Compras_Pots);
            Reset(dt_FechaMiami_LO_1);
            Reset(txt_refMiamo_LO_1);
            Reset(dt_FechaTech_LO_1);
            Reset(txt_refTech_LO_1)
        )
    )
)

UpdateContext(
    {
        AbrirCompletar: false,
        seleccion: false
    }
);
Refresh(Compras_Pots);
Reset(dt_FechaMiami_LO_1);
Reset(txt_refMiamo_LO_1);
Reset(dt_FechaTech_LO_1);
Reset(txt_refTech_LO_1);
Reset(drp_MetodoTransporte_LO_1);
Reset(drp_TipoEnvio_LO_1)

UpdateContext(
    {
        AbrirCompletar: false,
        seleccion: false
    }
);
Refresh(Compras_Pots);
Reset(dt_FechaMiami_LO_1);
Reset(txt_refMiamo_LO_1);
Reset(dt_FechaTech_LO_1);
Reset(txt_refTech_LO_1);
Reset(drp_MetodoTransporte_LO_1);
Reset(drp_TipoEnvio_LO_1);

If(
    IsBlank(drp_Maquina_HC_1.Selected.Maquina),
    UpdateContext(
        {
            Aviso: {
                Ver: true,
                Texto: "Debe seleccionar una maquina",
                Tipo: 0
            }
        }
    ),
    IsEmpty(glr_Materiales_HC_1.AllItems),
    UpdateContext(
        {
            Aviso: {
                Ver: true,
                Texto: "La lista de materiales no puede estar vacia",
                Tipo: 0
            }
        }
    ),
    IsBlank(drp_Empleado_HC_1.Selected.Nombre),
    UpdateContext(
        {
            Aviso: {
                Ver: true,
                Texto: "Debe seleccionar a un Operario",
                Tipo: 0
            }
        }
    ),
    UpdateContext({Guardando: true});
    ForAll(
        glr_Materiales_HC_1.AllItems,
        If(
            ThisRecord.nmb_Entregar_HC_1.Value > 0,
            If(
                IsBlank(
                    With(
                        {
                            or: ThisRecord.Orden,
                            op: ThisRecord.Operacion,
                            ma: ThisRecord.Material
                        },
                        LookUp(
                            Controlador_Herramientas,
                            Orden = or && Operacion = op && Material = ma && Maquina = drp_Maquina_HC_1.Selected.Maquina
                        )
                    )
                ),
                Collect(
                    Controlador_Herramientas,
                    {
                        Maquina: drp_Maquina_HC_1.Selected.Maquina,
                        Orden: ThisRecord.Orden,
                        Operacion: ThisRecord.Operacion,
                        'P/N': ThisRecord.'P/N',
                        Material: ThisRecord.Material,
                        Descripcion: ThisRecord.Descripcion,
                        Fecha: Today(),
                        Hora: Value(
                            Text(
                                Now(),
                                "HH"
                            )
                        ),
                        Entregado: ThisRecord.nmb_Entregar_HC_1.Value,
                        Produccion_Hecha: 0,
                        Produccion_Meta: Value(ThisRecord.txt_Meta_HC_1.Text),
                        User: txt_User_HC_1.Text,
                        Operario: drp_Empleado_HC_1.Selected.Nombre
                    }
                );
                Patch(
                    Controlador_Bodegas,
                    With(
                        {
                            or: ThisRecord.Orden,
                            op: ThisRecord.Operacion,
                            ma: ThisRecord.Material
                        },
                        LookUp(
                            Controlador_Bodegas,
                            Orden = or && Operacion = op && Material = ma
                        )
                    ),
                    {Usado: ThisRecord.Usado + ThisRecord.nmb_Entregar_HC_1.Value}
                ),
                With(
                    {
                        herramienta: With(
                            {
                                or: ThisRecord.Orden,
                                op: ThisRecord.Operacion,
                                ma: ThisRecord.Material
                            },
                            LookUp(
                                Controlador_Herramientas,
                                Orden = or && Operacion = op && Material = ma && Maquina = drp_Maquina_HC_1.Selected.Maquina
                            )
                        )
                    },
                    Collect(
                        Controlador_Herramienta_Historials,
                        {
                            Orden: herramienta.Orden,
                            Operacion: herramienta.Operacion,
                            'P/N': herramienta.'P/N',
                            Maquina: herramienta.Maquina,
                            Material: herramienta.Material,
                            Descripcion: herramienta.Descripcion,
                            Entregado: herramienta.Entregado,
                            Produccion_Hecha: herramienta.Produccion_Hecha,
                            Produccion_Meta: herramienta.Produccion_Meta,
                            Fecha: herramienta.Fecha,
                            Hora: herramienta.Hora,
                            Operario: herramienta.Operario,
                            User: herramienta.User
                        }
                    )
                );
                Patch(
                    Controlador_Herramientas,
                    With(
                        {
                            or: ThisRecord.Orden,
                            op: ThisRecord.Operacion,
                            ma: ThisRecord.Material
                        },
                        LookUp(
                            Controlador_Herramientas,
                            Orden = or && Operacion = op && Material = ma && Maquina = drp_Maquina_HC_1.Selected.Maquina
                        )
                    ),
                    {
                        Fecha: Today(),
                        Hora: Value(
                            Text(
                                Now(),
                                "HH"
                            )
                        ),
                        Entregado: ThisRecord.nmb_Entregar_HC_1.Value,
                        Produccion_Hecha: 0,
                        Produccion_Meta: Value(ThisRecord.txt_Meta_HC_1.Text),
                        User: txt_User_HC_1.Text,
                        Operario: drp_Empleado_HC_1.Selected.Nombre
                    }
                );
                Patch(
                    Controlador_Bodegas,
                    With(
                        {
                            or: ThisRecord.Orden,
                            op: ThisRecord.Operacion,
                            ma: ThisRecord.Material
                        },
                        LookUp(
                            Controlador_Bodegas,
                            Orden = or && Operacion = op && Material = ma
                        )
                    ),
                    {Usado: ThisRecord.Usado + ThisRecord.nmb_Entregar_HC_1.Value}
                )
            )
        )
    );
    Reset(glr_Materiales_HC_1);
    Refresh(Controlador_Herramientas);
    UpdateContext({Guardando: false})
)

UpdateContext(
    {
        AbrirCompletar: false,
        seleccion: false
    }
);
Refresh(Compras_Pots);
Reset(dt_FechaMiami_LO_1);
Reset(txt_refMiamo_LO_1);
Reset(dt_FechaTech_LO_1);
Reset(txt_refTech_LO_1);
Reset(drp_MetodoTransporte_LO_1);
Reset(drp_TipoEnvio_LO_1);
Reset(txt_Pot_LO_1);
Reset(txt_Requisi_LO_1);
Reset(drp_Tipo_LO_1);
Reset(drp_Trans_LO_1);
Back()
